import osimport timeimport subprocessimport threadingimport tracebackclass SystemWatchdog:    def __init__(self, required_files, heartbeat_check_func=None):        self.required_files = required_files        self.heartbeat_check = heartbeat_check_func        self.is_running = False        self.last_heartbeat = time.time()        self._pid = os.getpid()        self._log = os.path.join(            os.path.dirname(os.path.abspath(__file__)), "watchdog.log"        )    def start(self):        self.is_running = True        self.last_heartbeat = time.time()        threading.Thread(target=self._monitor_loop, daemon=True).start()    def stop(self):        self.is_running = False    def ping_heartbeat(self):        self.last_heartbeat = time.time()    def _trigger_emergency(self, reason):        self.is_running = False        try:            with open(self._log, "a", encoding="utf-8") as f:                f.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {reason}\n")        except Exception:            traceback.print_exc()        if os.name == "nt":            try:                subprocess.Popen(                    ["taskkill", "/f", "/pid", str(self._pid)],                    shell=True,                    creationflags=subprocess.CREATE_NO_WINDOW,                )            except Exception:                os._exit(1)        else:            os._exit(1)    def _monitor_loop(self):        while self.is_running:            for path in self.required_files:                if not os.path.exists(path):                    self._trigger_emergency(                        f"Critical file missing: {os.path.basename(path)}"                    )                    return            if self.heartbeat_check and time.time() - self.last_heartbeat > 6.0:                self._trigger_emergency("Main app frozen/unresponsive")                return            time.sleep(1.0)